SELECT e.event_id,a.student_id case_id,e.activity,e.timestamp FROM (SELECT 'LC:assignment:' || assignment_id || ':2' event_id, 'Assignment Submitted' activity, assignment_submitted_at timestamp FROM assignment WHERE assignment_submitted_at IS NOT NULL) e JOIN assignment a ON e.event_id='LC:assignment:' || a.assignment_id || ':2' ORDER BY case_id,timestamp,event_id;
